engine.buildEli5Prompt:
function buildEli5Prompt(opts) {
  opts = opts || {};
  var age = String(opts.age || "14");
  var detailLevel = String(opts.detailLevel || "1");
  var persona = String(opts.persona || "");
  var instructions = String(opts.instructions || "");
  var docText = String(opts.docText || "");

  var detailInstruction = "Keep it concise and to the point. Focus only on the most critical information.";
  if (detailLevel === "2") {
    detailInstruction =
      "Provide a comprehensive explanation. For every key point, add a sentence explaining 'Why this matters'. Expand on the definitions.";
  } else if (detailLevel === "3") {
    detailInstruction =
      "Provide an exhaustive, deep-dive explanation. Leave no concept unexplained. Include a specific 'Example Scenario' for the main topics to illustrate how they work in real life. Ensure the reader walks away with expert-level understanding (but in simple language).";
  }

  var structureExtra = detailLevel === "3"
    ? "- **Real World Example:** A hypothetical scenario illustrating the concept."
    : "";

  var prompt =
    persona + "\n" +
    "TASK: Explain this document content (whether a Legal Agreement or Scientific Publication) to an audience of age " + age + ".\n" +
    "GUIDELINES:\n" +
    "1. " + instructions + "\n" +
    "2. DEPTH: " + detailInstruction + "\n" +
    "3. STRUCTURE:\n" +
    "   - **The Gist:** A summary of what this document is about.\n" +
    "   - **Key Points:** Bullet points of the most important concepts or rules.\n" +
    "   - **Why It Matters:** The impact, risks, or conclusions.\n" +
    "   " + structureExtra + "\n" +
    "4. FORMAT: Use HTML formatting (<b>, <ul>, <li>, <br>). Do NOT use Markdown blocks.\n" +
    "DOCUMENT CONTENT:\n\n" +
    docText.substring(0, 500000);

  return prompt;
}

// Sanitize the AI response — strip markdown fences, convert **bold**
// to <b>, collapse extra newlines, replace remaining \n with <br>.
// FROM v2 runEli5Analysis lines 68-74 (verbatim).

engine.cleanEli5Html:
function cleanEli5Html(text) {
  if (!text) return "";
  return String(text)
    .replace(/```html/g, "")
    .replace(/```/g, "")
    .replace(/\*\*(.*?)\*\*/g, "<b>$1</b>")
    .replace(/>\s*[\r\n]+\s*/g, ">")
    .replace(/\n{2,}/g, "\n")
    .replace(/\n/g, "<br>");
}

// Per-age short description shown next to the slider. FROM v2 line 75.

engine.eli5AgeDescription:
function eli5AgeDescription(age) {
  var map = {
    10: "Simplifies everything into analogies and basic sentences. Removes all jargon.",
    14: "Explains concepts clearly using standard language. Defines complex terms.",
    18: "Professional but accessible summary. Removes unnecessary legalese but keeps nuance.",
  };
  return map[String(age)] || map["14"];
}

view.renderEli5UI:
function renderEli5UI(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  opts = opts || {};
  var mount = opts.mount;
  if (!mount) return null;
  var onRun  = opts.onRun  || function () {};
  var onHome = opts.onHome || function () {};
  var ageDescription = opts.ageDescription || function () { return ""; };

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_e5_root";

  root.innerHTML =
    // Header bar — v2 createConfigHeader equivalent.
    '<div class="_eli3_e5_bar">' +
      '<button type="button" class="_eli3_e5_back" title="Back">←</button>' +
      '<div class="_eli3_e5_title">🧸 ELI5: Explain It</div>' +
      '<div class="_eli3_e5_overview">SIMPLIFICATION ENGINE</div>' +
    '</div>' +
    '<div class="_eli3_e5_body">' +
      // Source picker card — blue accent.
      '<div class="_eli3_e5_card _eli3_e5_card_blue">' +
        '<div class="_eli3_e5_card_label">1. SELECT SOURCE</div>' +
        '<div class="_eli3_e5_source_row">' +
          '<label class="_eli3_e5_source_opt _eli3_e5_source_active" data-source="active">' +
            '<input type="radio" name="_eli3_e5_source" value="active" checked>' +
            '<span class="_eli3_e5_source_icon">📄</span>' +
            '<span class="_eli3_e5_source_text">Active Doc</span>' +
          '</label>' +
          '<label class="_eli3_e5_source_opt" data-source="upload">' +
            '<input type="radio" name="_eli3_e5_source" value="upload">' +
            '<span class="_eli3_e5_source_icon">📂</span>' +
            '<span class="_eli3_e5_source_text">Upload File</span>' +
          '</label>' +
        '</div>' +
        '<div class="_eli3_e5_upload_area" id="_eli3_e5_upload_area" hidden>' +
          '<div class="_eli3_e5_upload_icon">📂</div>' +
          '<div class="_eli3_e5_upload_label">Click to Upload PDF or Word</div>' +
          '<div class="_eli3_e5_upload_filename" id="_eli3_e5_filename"></div>' +
        '</div>' +
        '<input type="file" id="_eli3_e5_fileinput" accept=".docx,.pdf,.txt" hidden>' +
      '</div>' +
      // Age card — amber accent.
      '<div class="_eli3_e5_card _eli3_e5_card_amber">' +
        '<div class="_eli3_e5_card_header">' +
          '<div class="_eli3_e5_card_label _eli3_e5_label_amber">2. TARGET AUDIENCE AGE</div>' +
          '<div class="_eli3_e5_age_chip" id="_eli3_e5_age">14</div>' +
        '</div>' +
        '<input type="range" id="_eli3_e5_age_slider" class="_eli3_e5_slider _eli3_e5_slider_amber" min="10" max="18" step="4" value="14">' +
        '<div class="_eli3_e5_slider_legend">' +
          '<span>👶 10 (Simple)</span>' +
          '<span>High School (Standard)</span>' +
          '<span>🎓 18 (Detail)</span>' +
        '</div>' +
        '<div class="_eli3_e5_age_desc" id="_eli3_e5_age_desc">' + _esc(ageDescription(14)) + '</div>' +
      '</div>' +
      // Detail card — purple accent. Collapsed by default.
      '<div class="_eli3_e5_card _eli3_e5_card_purple">' +
        '<div class="_eli3_e5_detail_head" id="_eli3_e5_detail_head">' +
          '<div class="_eli3_e5_card_label _eli3_e5_label_purple">3. DEPTH OF RESPONSE (OPTIONAL)</div>' +
          '<div class="_eli3_e5_detail_arrow" id="_eli3_e5_detail_arrow">▼</div>' +
        '</div>' +
        '<div class="_eli3_e5_detail_body" id="_eli3_e5_detail_body" hidden>' +
          '<div class="_eli3_e5_detail_row">' +
            '<div class="_eli3_e5_detail_lbl_text">Level of Detail:</div>' +
            '<div class="_eli3_e5_detail_chip" id="_eli3_e5_detail_label">Standard</div>' +
          '</div>' +
          '<input type="range" id="_eli3_e5_detail_slider" class="_eli3_e5_slider _eli3_e5_slider_purple" min="1" max="3" step="1" value="1">' +
          '<div class="_eli3_e5_slider_legend">' +
            '<span>Standard</span>' +
            '<span>Enhanced</span>' +
            '<span>Deep Dive</span>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '<button type="button" id="_eli3_e5_run" class="_eli3_e5_run_btn">🚀 EXPLAIN IT!</button>' +
      // Results pane (hidden until first run).
      '<div class="_eli3_e5_results" id="_eli3_e5_results" hidden></div>' +
    '</div>';
  mount.appendChild(root);

  // Wire interactions.
  var ageSlider    = root.querySelector("#_eli3_e5_age_slider");
  var ageChip      = root.querySelector("#_eli3_e5_age");
  var ageDescEl    = root.querySelector("#_eli3_e5_age_desc");
  var detailSlider = root.querySelector("#_eli3_e5_detail_slider");
  var detailLabel  = root.querySelector("#_eli3_e5_detail_label");
  var detailHead   = root.querySelector("#_eli3_e5_detail_head");
  var detailBody   = root.querySelector("#_eli3_e5_detail_body");
  var detailArrow  = root.querySelector("#_eli3_e5_detail_arrow");
  var uploadArea   = root.querySelector("#_eli3_e5_upload_area");
  var fileInput    = root.querySelector("#_eli3_e5_fileinput");
  var fileNameEl   = root.querySelector("#_eli3_e5_filename");
  var runBtn       = root.querySelector("#_eli3_e5_run");
  var backBtn      = root.querySelector("._eli3_e5_back");
  var resultsEl    = root.querySelector("#_eli3_e5_results");
  var sourceOpts   = root.querySelectorAll("._eli3_e5_source_opt");

  ageSlider.oninput = function () {
    ageChip.textContent = ageSlider.value;
    ageDescEl.textContent = ageDescription(ageSlider.value);
  };
  var detailMap = { 1: "Standard", 2: "Enhanced", 3: "Deep Dive" };
  detailSlider.oninput = function () {
    detailLabel.textContent = detailMap[detailSlider.value] || "Standard";
  };
  detailHead.onclick = function () {
    if (detailBody.hasAttribute("hidden")) {
      detailBody.removeAttribute("hidden");
      detailArrow.textContent = "▲";
    } else {
      detailBody.setAttribute("hidden", "");
      detailArrow.textContent = "▼";
    }
  };

  // Source picker — toggle "active" / "upload" state, show/hide upload area.
  var _mode = "active";
  var _uploadedPayload = null;
  Array.prototype.forEach.call(sourceOpts, function (opt) {
    opt.onclick = function () {
      var src = opt.getAttribute("data-source");
      _mode = src;
      sourceOpts.forEach(function (o) { o.classList.remove("_eli3_e5_source_active"); });
      opt.classList.add("_eli3_e5_source_active");
      var radio = opt.querySelector('input[type="radio"]');
      if (radio) radio.checked = true;
      if (src === "upload") uploadArea.removeAttribute("hidden");
      else uploadArea.setAttribute("hidden", "");
    };
  });

  uploadArea.onclick = function () { fileInput.click(); };
  fileInput.onchange = function () {
    var file = fileInput.files && fileInput.files[0];
    if (!file) return;
    fileNameEl.textContent = "⏳ Reading " + file.name + "…";
    if (typeof opts.onReadFile === "function") {
      Promise.resolve(opts.onReadFile(file)).then(function (payload) {
        _uploadedPayload = payload;
        fileNameEl.innerHTML = "✅ <strong>" + _esc(file.name) + "</strong> ready.";
        uploadArea.classList.add("_eli3_e5_upload_ready");
      }).catch(function () {
        fileNameEl.textContent = "⚠️ Failed to read " + file.name;
      });
    }
  };

  runBtn.onclick = function () {
    if (_mode === "upload" && !_uploadedPayload) {
      if (typeof showToast === "function") showToast("Please upload a file first", "warn");
      return;
    }
    runBtn.disabled = true;
    runBtn.textContent = "⏳ Explaining…";
    resultsEl.setAttribute("hidden", "");
    Promise.resolve(onRun({
      age: ageSlider.value,
      detailLevel: detailSlider.value,
      mode: _mode,
      uploadedPayload: _uploadedPayload,
      resultsEl: resultsEl,
    })).then(function (res) {
      runBtn.disabled = false;
      runBtn.textContent = "🚀 EXPLAIN IT!";
      if (res && res.html) {
        renderEli5Result(resultsEl, res.html, ageSlider.value);
      }
    }).catch(function () {
      runBtn.disabled = false;
      runBtn.textContent = "🚀 EXPLAIN IT!";
    });
  };

  backBtn.onclick = onHome;

  return { refresh: function () {} };
}

// Render the AI explanation into the results pane.

view.renderEli5Result:
function renderEli5Result(target, html, age) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  if (!target) return;
  target.removeAttribute("hidden");
  target.innerHTML =
    '<div class="_eli3_e5_results_header">' +
      '<div class="_eli3_e5_results_title">EXPLANATION · AGE ' + _esc(age) + '</div>' +
      '<button type="button" class="_eli3_e5_copy_btn">📋 Copy</button>' +
    '</div>' +
    '<div class="_eli3_e5_results_body">' + html + '</div>';
  var copyBtn = target.querySelector("._eli3_e5_copy_btn");
  if (copyBtn) {
    copyBtn.onclick = function () {
      var body = target.querySelector("._eli3_e5_results_body");
      var text = body ? body.innerText : "";
      try { navigator.clipboard.writeText(text); } catch (e) {}
      copyBtn.textContent = "✅ Copied";
      setTimeout(function () { copyBtn.textContent = "📋 Copy"; }, 1500);
    };
  }
  if (target.scrollIntoView) target.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["eli5"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var buildEli5Prompt    = efns.buildEli5Prompt;
  var cleanEli5Html      = efns.cleanEli5Html;
  var eli5AgeDescription = efns.eli5AgeDescription;
  var renderEli5UI       = vfns.renderEli5UI;
  if (!buildEli5Prompt || !renderEli5UI) {
    eli.log.event("tool", "eli5_load_failed", {
      hasEngine: !!buildEli5Prompt, hasView: !!renderEli5UI,
    });
    return;
  }

  // ─── Tile handler ────────────────────────────────────────────────
  function _open() {
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      if (typeof showToast === "function") showToast("Dashboard root missing — try reopening ELI", "err");
      return;
    }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedEli5"); } catch (e) {}
    renderEli5UI({
      mount: mount,
      ageDescription: eli5AgeDescription,
      onReadFile: _readFile,
      onRun: _run,
      onHome: function () {
        try { eli.fsm.transition("idle"); } catch (e) {}
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
        else if (typeof showHome === "function") showHome();
      },
    });
  }

  // ─── File reader (uses cross-tool window.handleFileSelect bridge) ─
  function _readFile(file) {
    return new Promise(function (resolve, reject) {
      if (typeof window.handleFileSelect === "function") {
        window.handleFileSelect(file, function (payload) { resolve(payload); });
      } else {
        // Fallback — read as text.
        var reader = new FileReader();
        reader.onload = function () { resolve(reader.result); };
        reader.onerror = function () { reject(new Error("File read failed")); };
        reader.readAsText(file);
      }
    });
  }

  // ─── Read active doc text ────────────────────────────────────────
  function _readActiveDocText() {
    if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve("");
    return eli.host.runRaw("eli5:read_doc", function (context) {
      var body = context.document.body;
      body.load("text");
      return context.sync().then(function () { return body.text || ""; });
    }).catch(function () { return ""; });
  }

  // ─── Load prompts from IDB ──────────────────────────────────────
  // FROM v2 `getPrompt(key)` — reads from store "prompts" where each
  // row is `{ id: key, text: "..." }`. Map age → persona+instructions.
  function _loadPromptsForAge(age) {
    var personaKey = "explainPersonaTeen";
    var instructionsKey = "explainInstructionsTeen";
    if (String(age) === "10") {
      personaKey = "explainPersonaChild";
      instructionsKey = "explainInstructionsChild";
    } else if (String(age) === "18") {
      personaKey = "explainPersonaAdult";
      instructionsKey = "explainInstructionsAdult";
    }
    var pP = eli.storage.get("prompts", personaKey).catch(function () { return null; });
    var pI = eli.storage.get("prompts", instructionsKey).catch(function () { return null; });
    return Promise.all([pP, pI]).then(function (rows) {
      var persona = rows[0] && rows[0].text ? rows[0].text : "ACT AS: A helpful explainer.";
      var instructions = rows[1] && rows[1].text ? rows[1].text :
        "Use clear, age-appropriate language. Define jargon. Be accurate.";
      return { persona: persona, instructions: instructions };
    });
  }

  // ─── Run the explainer ──────────────────────────────────────────
  function _run(input) {
    var age = String(input.age || "14");
    var detailLevel = String(input.detailLevel || "1");
    var mode = input.mode || "active";
    var uploadedPayload = input.uploadedPayload;

    var docTextPromise;
    var isPdf = false;
    if (mode === "upload") {
      if (uploadedPayload && typeof uploadedPayload === "object" && uploadedPayload.isBase64) {
        isPdf = true;
        docTextPromise = Promise.resolve("[PDF binary attached]");
      } else {
        docTextPromise = Promise.resolve(String(uploadedPayload || ""));
      }
    } else {
      docTextPromise = _readActiveDocText();
    }

    return Promise.all([docTextPromise, _loadPromptsForAge(age)]).then(function (parts) {
      var docText = parts[0];
      var prompts = parts[1];
      if (!docText || docText.trim().length < 10) {
        if (typeof showToast === "function") showToast("No document text to explain.", "warn");
        return null;
      }
      var prompt = buildEli5Prompt({
        age: age,
        detailLevel: detailLevel,
        persona: prompts.persona,
        instructions: prompts.instructions,
        docText: docText,
      });

      // For PDFs, v2 sent inlineData. v3 kernel's eli.ai.complete signature
      // doesn't support inlineData parts directly; fall back to text-only
      // and warn the user that PDF extraction needs a text source.
      if (isPdf) {
        if (typeof showToast === "function") {
          showToast("PDF binary mode requires text extraction — upload as .docx or .txt for best results", "warn");
        }
      }

      if (typeof showToast === "function") showToast("⏳ Generating explanation…", "info");
      return eli.ai.complete(prompt, { maxTokens: 4000 }).then(function (response) {
        if (!response) return null;
        var cleanHtml = cleanEli5Html(response);
        // Wrongness capture for replay (only the shape; sanitize doc text).
        try {
          if (eli.capture && eli.capture.engineRun) {
            eli.capture.engineRun("eli5", {
              age: age, detailLevel: detailLevel, mode: mode,
              docTextLen: docText.length,
            }, { responseLen: String(response).length });
          }
        } catch (e) {}
        try { if (eli.stats && eli.stats.record) eli.stats.record("eli5Explanations"); } catch (e) {}
        return { html: cleanHtml };
      });
    }).catch(function (e) {
      if (typeof showToast === "function") {
        showToast("ELI5 failed: " + (e && e.message || "unknown"), "err");
      }
      eli.log.event("tool", "eli5_run_failed", { msg: e && e.message });
      return null;
    });
  }

  // ─── Channels ────────────────────────────────────────────────────
  eli.register({
    tile: { app_eli5: _open },
    eli5: { open: _open },
    activity_restore: { eli5: function () { _open(); } },
  });

  // Back-compat globals so the v2 catalog action "showEli5App()" keeps
  // working for any cross-tool callers that still reference it.
  window.showEli5App = _open;

  eli.log.event("tool", "eli5_initialized", {});
}

jsonTools.css:
/* tools/eli5/style.css — ELI5 panel.
   Mirrors v2's three-card stacked layout (Source / Age / Detail) with
   colored left accents (blue / amber / purple). Injected as
   <style data-tool="eli5">. */

._eli3_e5_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
  box-sizing: border-box;
}

/* Header — standard v3 tool-hub navy + gold. */
._eli3_e5_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_e5_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_e5_back:hover { color: #f2d866; }
._eli3_e5_title {
  flex: 1;
  font: 800 16px/1.2 'Georgia', serif;
  color: #ffffff;
}
._eli3_e5_overview {
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 1px;
  color: #e5cc80;
  text-transform: uppercase;
}

._eli3_e5_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  display: flex; flex-direction: column;
  gap: 14px;
}

/* Stacked cards with colored left accent. */
._eli3_e5_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 5px solid #1565c0;
  padding: 14px;
  display: flex; flex-direction: column;
  gap: 8px;
  animation: _eli3_e5_slidein 0.3s ease;
}
@keyframes _eli3_e5_slidein {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}
._eli3_e5_card_blue   { border-left-color: #1565c0; }
._eli3_e5_card_amber  { border-left-color: #fbc02d; }
._eli3_e5_card_purple { border-left-color: #7b1fa2; }

._eli3_e5_card_label {
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #1565c0;
}
._eli3_e5_label_amber  { color: #ef6c00; }
._eli3_e5_label_purple { color: #7b1fa2; }
._eli3_e5_card_header {
  display: flex; justify-content: space-between; align-items: center;
}

/* Source picker — two-tile radio. */
._eli3_e5_source_row {
  display: flex; gap: 10px;
}
._eli3_e5_source_opt {
  flex: 1;
  background: #f5f5f5;
  border: 1px solid #ddd;
  padding: 10px;
  cursor: pointer;
  display: flex; align-items: center; gap: 8px;
  font: 700 11px/1 'Inter', sans-serif;
  color: #546e7a;
  transition: all 0.15s;
}
._eli3_e5_source_opt._eli3_e5_source_active {
  background: #e3f2fd;
  border-color: #2196f3;
  color: #1565c0;
}
._eli3_e5_source_opt input[type="radio"] {
  transform: scale(1.2);
  accent-color: #1565c0;
}
._eli3_e5_source_icon { font-size: 14px; }
._eli3_e5_source_text { font-weight: 700; }

._eli3_e5_upload_area {
  border: 2px dashed #90caf9;
  background: #f0f7ff;
  padding: 15px;
  text-align: center;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
._eli3_e5_upload_area:hover {
  background: #e3f2fd;
  border-color: #1565c0;
}
._eli3_e5_upload_icon { font-size: 20px; }
._eli3_e5_upload_label { font: 700 11px/1.2 'Inter', sans-serif; color: #1565c0; margin-top: 2px; }
._eli3_e5_upload_filename { font: 500 10px/1.2 'Inter', sans-serif; color: #555; margin-top: 4px; }
._eli3_e5_upload_ready {
  background: #e8f5e9;
  border-color: #2e7d32;
}

/* Age slider — amber theme. */
._eli3_e5_age_chip {
  font: 800 14px/1 'Inter', sans-serif;
  color: #f57f17;
  background: #fff3e0;
  padding: 2px 8px;
}
._eli3_e5_slider {
  width: 100%;
  cursor: pointer;
}
._eli3_e5_slider_amber  { accent-color: #f57f17; }
._eli3_e5_slider_purple { accent-color: #7b1fa2; }
._eli3_e5_slider_legend {
  display: flex; justify-content: space-between;
  font: 600 10px/1 'Inter', sans-serif;
  color: #78909c;
}
._eli3_e5_age_desc {
  margin-top: 6px;
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #5d4037;
  font-style: italic;
  background: #fff8e1;
  padding: 8px;
}

/* Detail slider — purple theme, collapsible. */
._eli3_e5_detail_head {
  display: flex; justify-content: space-between; align-items: center;
  cursor: pointer;
}
._eli3_e5_detail_arrow {
  font: 600 12px/1 'Inter', sans-serif;
  color: #7b1fa2;
  transition: transform 0.15s;
}
._eli3_e5_detail_body {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid #f3e5f5;
  display: flex; flex-direction: column;
  gap: 6px;
}
._eli3_e5_detail_body[hidden] { display: none; }
._eli3_e5_detail_row {
  display: flex; justify-content: space-between; align-items: center;
}
._eli3_e5_detail_lbl_text {
  font: 500 11px/1 'Inter', sans-serif;
  color: #666;
}
._eli3_e5_detail_chip {
  font: 800 11px/1 'Inter', sans-serif;
  color: #7b1fa2;
  background: #f3e5f5;
  padding: 2px 8px;
}

/* Run button — primary platinum / blue. */
._eli3_e5_run_btn {
  width: 100%;
  padding: 14px;
  font: 800 13px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: none;
  cursor: pointer;
  transition: box-shadow 0.15s;
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.3);
}
._eli3_e5_run_btn:hover:not(:disabled) {
  box-shadow: 0 6px 18px rgba(21, 101, 192, 0.45);
}
._eli3_e5_run_btn:disabled { opacity: 0.6; cursor: not-allowed; }

/* Results pane. */
._eli3_e5_results {
  background: #fff;
  border: 1px solid #cfd8dc;
  border-top: 5px solid #2e7d32;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.05);
  padding: 16px;
}
._eli3_e5_results_header {
  display: flex; justify-content: space-between; align-items: center;
  padding-bottom: 10px;
  border-bottom: 1px dashed #ccc;
  margin-bottom: 12px;
}
._eli3_e5_results_title {
  font: 800 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #2e7d32;
}
._eli3_e5_copy_btn {
  background: none;
  border: none;
  color: #90a4ae;
  cursor: pointer;
  font: 500 12px/1 'Inter', sans-serif;
}
._eli3_e5_copy_btn:hover { color: #1565c0; }
._eli3_e5_results_body {
  font: 400 14px/1.5 'Segoe UI', sans-serif;
  color: #37474f;
}
._eli3_e5_results_body b { color: #1e293b; }
._eli3_e5_results_body ul {
  padding-left: 20px;
  margin: 6px 0;
}
._eli3_e5_results_body li { margin-bottom: 4px; }
